const claimResult = (incident: Incident, policy: Policy): ClaimResult => {
  const payout = incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage),
    0,
  );
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

const runStep = (
  step: Step,
  customer: Customer,
  quoteOrdinal: number,
  policies: Map<number, Policy>,
  stepIndex: number,
): StepResult => {
  if (step.op === "quote") {
    policies.set(stepIndex, policyFor(step.items));
    return quoteResult(step.items, customer, quoteOrdinal);
  }
  const policy = policies.get(step.policy);
  if (policy === undefined) {
    throw new Error(`No policy created by step ${step.policy}`);
  }
  return claimResult(step.incident, policy);
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  let quoteOrdinal = FIRST_QUOTE_ORDINAL;
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, stepIndex) => {
    const result = runStep(
      step,
      scenario.customer,
      quoteOrdinal,
      policies,
      stepIndex,
    );
    if (step.op === "quote") quoteOrdinal += 1;
    return result;
  });
  return { results };
};

